import java.util.*;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();

        long g = gcd(x, y);
        x /= g;
        y /= g;
        long q = x / y;
        long r = x % y;

        TreeMap<Double, TreeSet<Ratio>> result = new TreeMap<>();

        for (long b = 1; b <= n; b++) {
            g = gcd(y, b);
            long c = b / g;
            long z = y / g;
            long t = b * z;
            long u = q * t + r * c;

            saveRatio(result, u, z, b, c, z);
            if (u % z != 0) {
                saveRatio(result, u + z - 1, z, b, c, z);
            }
        }

        Map.Entry<Double, TreeSet<Ratio>> lastEntry = result.firstEntry();
        Ratio p = lastEntry.getValue().last();
        System.out.println(p.numerator + "/" + p.denominator);
    }

    static void saveRatio(TreeMap<Double, TreeSet<Ratio>> result, long a, long z, long b, long c, long y) {
        long g = gcd(a, b);
        double key = Math.abs((double)(a - b * y) / z);
        Ratio ratio = new Ratio(b / g, a / g);
        result.computeIfAbsent(key, k -> new TreeSet<>()).add(ratio);
    }

    static long gcd(long a, long b) {
        return BigInteger.valueOf(a).gcd(BigInteger.valueOf(b)).longValue();
    }

    static class Ratio implements Comparable<Ratio> {
        long numerator;
        long denominator;

        Ratio(long numerator, long denominator) {
            this.numerator = numerator;
            this.denominator = denominator;
        }

        @Override
        public int compareTo(Ratio other) {
            long lhs = this.numerator * other.denominator;
            long rhs = other.numerator * this.denominator;
            return Long.compare(lhs, rhs);
        }
    }
}
